package character

import (
	_ "embed"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"sync"

	"github.com/pietjan/valheim-save/internal/zpackage"
)

// The file names an item by its prefab's hash and stores the numbers the
// player has, not the limits. The limits, and the name the game shows, come
// from this table, dumped from a server's prefabs by tools/item-dump.cs and
// regenerated by items_gen.go (make items). The hash is the prefab name's
// StableHashCode, computed when the table loads, so the file's hashes
// resolve without a prefab table of their own.
//
//go:embed items.tsv
var itemsTable string

// ItemInfo is what the game's prefab says about an item.
type ItemInfo struct {
	Prefab             string
	Name               string // the game's English, "" when it has none
	Type               string // ItemDrop.ItemData.ItemType's name
	MaxStack           int
	MaxQuality         int
	MaxDurability      float32
	DurabilityPerLevel float32
	UseDurability      bool
	Teleportable       bool
	Weight             float32
}

// MaxDurabilityAt is the durability of a fresh item at a quality, as
// ItemData.GetMaxDurability computes it.
func (i ItemInfo) MaxDurabilityAt(quality int) float32 {
	return i.MaxDurability + float32(quality-1)*i.DurabilityPerLevel
}

// IsEquipment reports whether the item is something worn or wielded: a
// weapon, shield, armour piece, cape, tool, torch, utility or trinket.
// These are the items whose tooltip shows a crafter.
func (i ItemInfo) IsEquipment() bool {
	switch i.Type {
	case "OneHandedWeapon", "TwoHandedWeapon", "TwoHandedWeaponLeft", "Bow", "Shield", "Attach_Atgeir",
		"Helmet", "Chest", "Legs", "Hands", "Shoulder", "Torch", "Tool", "Utility", "Trinket":
		return true
	}
	return false
}

// Label is the name a player would read: the game's, or the prefab's when
// the game has none.
func (i ItemInfo) Label() string {
	if i.Name != "" {
		return i.Name
	}
	return i.Prefab
}

var (
	itemsOnce   sync.Once
	itemsByName map[string]*ItemInfo // prefab, lower case
	itemsByHash map[int32]*ItemInfo
	itemsList   []*ItemInfo
)

func loadItems() {
	itemsByName = make(map[string]*ItemInfo, 1200)
	itemsByHash = make(map[int32]*ItemInfo, 1200)
	for _, line := range strings.Split(itemsTable, "\n") {
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		f := strings.Split(line, "\t")
		if len(f) != 10 {
			continue
		}
		stack, _ := strconv.Atoi(f[2])
		maxQ, _ := strconv.Atoi(f[3])
		dur, _ := strconv.ParseFloat(f[4], 32)
		durLvl, _ := strconv.ParseFloat(f[5], 32)
		weight, _ := strconv.ParseFloat(f[8], 32)
		it := &ItemInfo{
			Prefab: f[0], Type: f[1], MaxStack: stack, MaxQuality: maxQ,
			MaxDurability: float32(dur), DurabilityPerLevel: float32(durLvl),
			UseDurability: f[6] == "1", Teleportable: f[7] == "1", Weight: float32(weight), Name: f[9],
		}
		itemsByName[strings.ToLower(it.Prefab)] = it
		itemsByHash[zpackage.StableHashCode(it.Prefab)] = it
		itemsList = append(itemsList, it)
	}
}

// LookupItem finds an item by prefab name, case insensitively.
func LookupItem(prefab string) (ItemInfo, bool) {
	itemsOnce.Do(loadItems)
	it, ok := itemsByName[strings.ToLower(prefab)]
	if !ok {
		return ItemInfo{}, false
	}
	return *it, true
}

// LookupItemHash finds an item by its prefab hash, the way the file names it.
func LookupItemHash(hash int32) (ItemInfo, bool) {
	itemsOnce.Do(loadItems)
	it, ok := itemsByHash[hash]
	if !ok {
		return ItemInfo{}, false
	}
	return *it, true
}

// FindItems matches a prefab name exactly or the game's name case
// insensitively, and failing both returns every item whose prefab or name
// contains the text, so the caller can say what was meant.
func FindItems(s string) []ItemInfo {
	itemsOnce.Do(loadItems)
	if it, ok := LookupItem(s); ok {
		return []ItemInfo{it}
	}
	var exact, partial []ItemInfo
	key := strings.ToLower(s)
	for _, it := range itemsList {
		name := strings.ToLower(it.Name)
		switch {
		case name == key:
			exact = append(exact, *it)
		case strings.Contains(name, key) || strings.Contains(strings.ToLower(it.Prefab), key):
			partial = append(partial, *it)
		}
	}
	if len(exact) > 0 {
		return exact
	}
	sort.Slice(partial, func(i, j int) bool { return partial[i].Prefab < partial[j].Prefab })
	return partial
}

// ItemLabel names an item by its prefab hash the way a player would read
// it: the game's name, or the prefab name when the game has none, or the
// hash when the table does not know the prefab.
func ItemLabel(hash int32) string {
	if it, ok := LookupItemHash(hash); ok {
		return it.Label()
	}
	return "hash " + strconv.FormatInt(int64(hash), 10)
}

// NewItem makes the item the game would have made had the character crafted
// it: a fresh one of the prefab at a quality with a full stack of count, the
// character as its crafter when it is equipment (the tooltip shows the name
// on a weapon or a piece of armour; a crafter on a stack of wood is noise),
// and the cheated bit off.
// The stack is capped at the prefab's maximum, as the game caps it on load;
// the quality is not, since the game does not either.
func NewItem(info ItemInfo, count, quality int, crafterID int64, crafterName string) (Item, error) {
	if count < 1 || quality < 1 {
		return Item{}, fmt.Errorf("count and quality must be at least 1")
	}
	if count > info.MaxStack {
		count = info.MaxStack
	}
	if quality > 0xFFFF || count > 0xFFFF {
		return Item{}, fmt.Errorf("count and quality must fit in 16 bits")
	}
	if !info.IsEquipment() {
		crafterID, crafterName = 0, ""
	}
	return Item{
		DurabilityCenti: int32(info.MaxDurabilityAt(quality) * 100),
		Quality:         uint16(quality),
		Stack:           uint16(count),
		CrafterID:       crafterID,
		CrafterName:     crafterName,
		HasPrefab:       true,
		PrefabHash:      zpackage.StableHashCode(info.Prefab),
	}, nil
}

// FreeSlot is the first empty slot in reading order, as the game fills
// them, or false when the inventory is full.
func (p *Player) FreeSlot() (x, y int, ok bool) {
	rows := p.InventoryRows()
	used := make(map[[2]int]bool, len(p.Inventory.Items))
	for _, it := range p.Inventory.Items {
		used[[2]int{int(it.GridX), int(it.GridY)}] = true
	}
	for y := 0; y < rows; y++ {
		for x := 0; x < InventoryWidth; x++ {
			if !used[[2]int{x, y}] {
				return x, y, true
			}
		}
	}
	return 0, 0, false
}

// AddItem puts count of an item into the inventory at a quality: first
// topping up stacks of the same prefab and quality, then filling free slots
// with new stacks, crafted by the character when the item is equipment, and
// returns how many it could not place. Stacking is by prefab and quality, as the game's own AddItem
// stacks; a topped-up stack keeps whatever crafter it had.
func (p *Profile) AddItem(info ItemInfo, count, quality int) (left int, err error) {
	if p.Player == nil {
		return count, fmt.Errorf("no player data")
	}
	return p.Player.addItem(info, count, quality, p.PlayerID, p.Name)
}

func (p *Player) addItem(info ItemInfo, count, quality int, crafterID int64, crafterName string) (left int, err error) {
	if count < 1 {
		return 0, fmt.Errorf("count must be at least 1")
	}
	hash := zpackage.StableHashCode(info.Prefab)
	left = count
	if info.MaxStack > 1 {
		for i := range p.Inventory.Items {
			it := &p.Inventory.Items[i]
			if it.PrefabHash != hash || int(it.Quality) != quality || int(it.Stack) >= info.MaxStack {
				continue
			}
			room := info.MaxStack - int(it.Stack)
			if room > left {
				room = left
			}
			it.Stack += uint16(room)
			left -= room
			if left == 0 {
				return 0, nil
			}
		}
	}
	for left > 0 {
		x, y, ok := p.FreeSlot()
		if !ok {
			return left, nil
		}
		it, err := NewItem(info, left, quality, crafterID, crafterName)
		if err != nil {
			return left, err
		}
		it.GridX, it.GridY = uint8(x), uint8(y)
		p.Inventory.Items = append(p.Inventory.Items, it)
		left -= int(it.Stack)
	}
	return 0, nil
}

// RemoveItemAt takes the item out of a slot, returning it, or false when
// the slot is empty.
func (p *Player) RemoveItemAt(x, y int) (Item, bool) {
	for i, it := range p.Inventory.Items {
		if int(it.GridX) == x && int(it.GridY) == y {
			p.Inventory.Items = append(p.Inventory.Items[:i], p.Inventory.Items[i+1:]...)
			return it, true
		}
	}
	return Item{}, false
}
